    /// ImageIO path it is the destination type
    /// `CGImageDestinationCreateWithURL` takes. Either way it is what the
    /// save panel's content type and file extension are derived from, which
    /// is why the two image formats name a real UTI here rather than
    /// nothing — an export that could not tell the panel it writes a `.gif`
    /// would be worse off than one whose type string a session would
    /// reject, and a session is never built for them.
    ///
    /// An APNG is written to an ordinary PNG destination — the animation
    /// lives in `acTL`/`fcTL` chunks inside a file that is still a PNG — so
    /// its type identifier is PNG's, not one of its own.
    ///
    /// The two LPCM rows' identifiers are exactly `AVFileType.wav` and
    /// `AVFileType.aiff`'s raw values, which is what lets
    /// `Exporter.fileType(for:)` resolve them from this string alone
    /// rather than growing a container list of its own.
    pub(crate) fn file_type(self) -> &'static str {
        match self {
            Container::Mov => "com.apple.quicktime-movie",
            Container::Mp4 => "public.mpeg-4",
            Container::M4a => "com.apple.m4a-audio",
            Container::Wav => "com.microsoft.waveform-audio",
            Container::Aiff => "public.aiff-audio",
            Container::Gif => "com.compuserve.gif",
            Container::Apng => "public.png",
        }
    }

    /// Whether `shouldOptimizeForNetworkUse` defaults on. MP4 and M4A are
    /// the delivery containers people upload, and a leading `moov` atom
    /// lets a player start before the file is fully fetched. A ProRes MOV
    /// is an editing master handed to another application, where the
    /// rewrite pass buys nothing. An HEVC-with-alpha MOV is a delivery file
    /// too, and its default stays off all the same: that was the owner's
    /// choice for the row (spec §11 G-33), and the override turns it on. GIF
    /// and APNG have no `moov` atom and nothing to move: a viewer already
    /// starts on the first frame, and
    /// neither do WAV and AIFF — a RIFF or an IFF file is a header
    /// followed by samples, with no index to relocate, so the flag would
    /// be a request the writer has nothing to do about.
    pub(crate) fn optimizes_for_network(self) -> bool {
        matches!(self, Container::Mp4 | Container::M4a)
    }

    /// Whether the container can hold sound. Every movie container can,
    /// and M4A, WAV and AIFF are nothing else; GIF and APNG are picture
    /// formats with no audio track in the file format at all, so
    /// `audio: false` for those is a fact about the container rather than
    /// a decision about the project.
    pub(crate) fn carries_audio(self) -> bool {
        !matches!(self, Container::Gif | Container::Apng)
    }
}
//! An HLG project's deliverables (spec §11 HD-5, HD-14): which picture an
//! export row writes — the HLG master, HDR10 (PQ) or the SDR version — and the
//! two refusals that keep a file from carrying a picture it cannot label.
//!
//! The vocabulary is three words, `hlg`, `pq` and `sdr`, spelled
//! `dynamic_range` both as an export override (`export_overrides.rs` reads it)
//! and as a recipe option (`recipe_options.rs`), because the two are one
//! decision seen from two sides: the export publishes its settings' `color` as
//! the recipe option of the key it draws, so the output pass the preview draws
//! for Show SDR Version is the one the file is written through.
//!
//! An SDR project is untouched by all of it: `deliverable` answers `None` for
//! every row there, so its settings carry no `color` and its recipes no
//! `dynamic_range`, and every SDR file and frame is the text and the bytes it
//! was.

use crate::export_table::Preset;
use crate::model::{CanvasOutput, Project};

/// The picture an HLG project's export or frame is drawn as (spec §11 HD-14).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DynamicRange {
    /// The working space itself, BT.2100 HLG: no output pass.
    Hlg,
    /// HDR10: the HLG display light at 1,000 cd/m² through ST 2084.
    Pq,
    /// The SDR version (spec §11 HD-4): the inverse of the lift with a
    /// shoulder above reference white, encoded Rec. 709.
    Sdr,
}

impl DynamicRange {
    /// The word for `text`, or `None` for anything else.
    pub fn parse(text: &str) -> Option<DynamicRange> {
        match text {
            "hlg" => Some(DynamicRange::Hlg),
            "pq" => Some(DynamicRange::Pq),
            "sdr" => Some(DynamicRange::Sdr),
            _ => None,
        }
    }

    /// The word as it is spelled in JSON.
    pub fn as_str(self) -> &'static str {
        match self {
            DynamicRange::Hlg => "hlg",
            DynamicRange::Pq => "pq",
            DynamicRange::Sdr => "sdr",
        }
    }
}

/// The rows that carry an HDR picture (spec §11 HD-5, CX-14): the four HDR
/// rows, all 10-bit. Every other video row of an HLG project writes the SDR
/// version.
pub(crate) const HDR_ROWS: [&str; 4] = ["hevc_10bit", "av1", "prores_422", "prores_4444"];

impl Project {
    /// What `preset` writes for this project when `asked` was requested
    /// (spec §11 HD-14 (c)): `None` for an audio row and for every row of an
    /// SDR project (nothing to label), else the resolved picture. An audio row
    /// reads the argument and ignores it, as a bitrate on a GIF is; an SDR
    /// project takes `sdr` as nothing; `hlg` and `pq` are refused in an SDR
    /// project and on a row that is not 10-bit, each in its own sentence.
    pub(crate) fn deliverable(
        &self,
        preset: &Preset,
        asked: Option<DynamicRange>,
    ) -> Result<Option<DynamicRange>, String> {
        if !preset.video {
            return Ok(None);
        }
        let hdr_asked = asked.filter(|range| *range != DynamicRange::Sdr);
        if self.canvas.output != CanvasOutput::Hlg {
            return match hdr_asked {
                Some(range) => Err(format!(
                    "dynamic_range \"{}\" needs an HLG project; set_canvas output \"hlg\" first",
                    range.as_str()
                )),
                None => Ok(None),
            };
        }
        if HDR_ROWS.contains(&preset.id) {
            return Ok(Some(asked.unwrap_or(DynamicRange::Hlg)));
        }
        match hdr_asked {
            Some(range) => Err(format!(
                "{} is 8-bit and writes the SDR version; export dynamic_range \"{}\" as \
                 hevc_10bit, av1, prores_422 or prores_4444",
                preset.id,
                range.as_str()
            )),
            None => Ok(Some(DynamicRange::Sdr)),
        }
    }
}
