//! Black-box tests for the WebM writer — spec §11 CX-6 and CX-15 (codec-export
//! C3) — driven through `rc_webm_*` exactly as the app's `ExportWebMWriter`
//! drives it, and read back two independent ways:
//!
//! 1. **Through #216-R's reader** (`framejob_core::container::Container`),
//!    the import path a WebM takes into Frame Job: the codecs, the `av1C`
//!    record, the colour and HDR10 blobs, OpusHead, the audio timed from the
//!    CodecDelay, the video retimed onto the grid at five rates, every
//!    payload's bytes and every sync flag.
//! 2. **Through `common/ebml_read.rs`'s walk**, for what that reader skips:
//!    the EBML header, Info's Duration, the track entries' timing fields,
//!    Chapters, Cues against the Clusters, the SeekHead, the Segment's size,
//!    DiscardPadding and the interleave order.
//!
//! And: a video-only layout writes each packet as it arrives; every refusal
//! by its sentence; two threads adding at once.

mod common;

use std::ffi::c_char;
use std::path::{Path, PathBuf};
use std::ptr;
use std::sync::atomic::{AtomicUsize, Ordering};

use serde_json::{json, Value};

use common::ebml_read::{self, blocks, segment, Element};
use common::{cstring, take_string};
use framejob_core::container::{Container, AUDIO, VIDEO};
use framejob_core::ffi_webm::{
    rc_webm_add_packet, rc_webm_end_track, rc_webm_finish, rc_webm_free, rc_webm_open, RcWebm,
};
use framejob_core::time::Fps;

const V: u32 = 1;
const A: u32 = 2;
/// An `av1C` record's bytes; the writer carries them opaque.
const AV1C: [u8; 10] = [0x81, 0x08, 0x0C, 0x00, 0x0A, 0x0B, 0x00, 0x00, 0x00, 0x2A];
/// HD-5's mastering display and content light level (spec §11 HD-14 (d)).
const MDCV: &str = "33c286c41d4c0bb884d03e803d13404200989680" ;
const MDCV_TAIL: &str = "00000032";
const CLLI: &str = "03e80000";
const PRE_SKIP: u16 = 312;
const SECOND: i64 = 1_000_000_000;

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn mdcv() -> String {
    format!("{MDCV}{MDCV_TAIL}")
}

/// A fresh path in the test's own folder.
fn temp_path(name: &str) -> PathBuf {
    static NEXT: AtomicUsize = AtomicUsize::new(0);
    let dir = std::env::temp_dir().join(format!("framejob-webm-{}", std::process::id()));
    std::fs::create_dir_all(&dir).expect("temporary folder");
    dir.join(format!("{}-{name}.webm", NEXT.fetch_add(1, Ordering::Relaxed)))
}

/// An open `RcWebm`, freed on drop. Shared across threads only by the test
/// that adds from two at once, which the header allows.
struct Webm(*mut RcWebm);

unsafe impl Send for Webm {}
unsafe impl Sync for Webm {}

impl Drop for Webm {
    fn drop(&mut self) {
        unsafe { rc_webm_free(self.0) };
    }
}

fn answer(ok: bool, err: *mut c_char) -> Result<(), String> {
    if ok {
        assert!(err.is_null(), "a true answer writes no err_out");
        Ok(())
    } else {
        Err(take_string(err).expect("a false answer writes err_out"))
    }
}

impl Webm {
    fn open(path: &Path, layout: &Value) -> Result<Webm, String> {
        let p = cstring(path.to_str().expect("a UTF-8 path"));
        let l = cstring(&layout.to_string());
        let mut err: *mut c_char = ptr::null_mut();
        let handle = unsafe { rc_webm_open(p.as_ptr(), l.as_ptr(), &mut err) };
        if handle.is_null() {
            return Err(take_string(err).expect("a NULL open writes err_out"));
        }
        assert!(err.is_null());
        Ok(Webm(handle))
    }

    fn add(&self, track: u32, pts: i64, key: bool, discard: i64, bytes: &[u8]) -> Result<(), String> {
        let mut err: *mut c_char = ptr::null_mut();
        let ok = unsafe {
            rc_webm_add_packet(self.0, track, pts, key, discard, bytes.as_ptr(), bytes.len(), &mut err)
        };
        answer(ok, err)
    }

    fn end(&self, track: u32) -> Result<(), String> {
        let mut err: *mut c_char = ptr::null_mut();
        let ok = unsafe { rc_webm_end_track(self.0, track, &mut err) };
        answer(ok, err)
    }

    fn finish(&self) -> Result<(), String> {
        let mut err: *mut c_char = ptr::null_mut();
        let ok = unsafe { rc_webm_finish(self.0, &mut err) };
        answer(ok, err)
    }
}

fn video_layout(fps: [u32; 2], pq: bool) -> Value {
    let mut colour = json!({"matrix": 9, "range": 1, "transfer": 16, "primaries": 9,
                            "bits_per_channel": 10});
    if pq {
        colour["mdcv_hex"] = json!(mdcv());
        colour["clli_hex"] = json!(CLLI);
    }
    json!({"codec_id": "V_AV1", "codec_private_hex": hex(&AV1C), "width": 640, "height": 360,
           "fps": fps, "colour": colour})
}

fn audio_layout() -> Value {
    json!({"codec_id": "A_OPUS", "channels": 2, "sample_rate": 48000, "pre_skip": PRE_SKIP})
}

/// The whole two-second layout: video at 30 fps (PQ), Opus, two chapters.
fn full_layout() -> Value {
    json!({
        "duration_ns": 2 * SECOND,
        "video": video_layout([30, 1], true),
        "audio": audio_layout(),
        "chapters": [
            {"start_ns": 0, "end_ns": SECOND, "name": "Intro"},
            {"start_ns": SECOND, "end_ns": 2 * SECOND, "name": "Body"}
        ]
    })
}

/// Frame `k`'s bytes: distinct, of varying length.
fn frame(k: usize) -> Vec<u8> {
    let mut out = vec![0x12, 0x00, (k & 0xFF) as u8, (k >> 8) as u8];
    out.extend((0..(20 + k % 7)).map(|i| (i * 31 + k) as u8));
    out
}

/// An Opus packet of one 20 ms stereo CELT frame (TOC config 31, code 0).
fn opus(k: usize) -> Vec<u8> {
    vec![0xFC, (k & 0xFF) as u8, 0x55, (k >> 8) as u8]
}

/// The video frame's time at `k`, as the app hands it: round(k · 1e9 · den / num).
fn frame_ns(k: usize, num: u32, den: u32) -> i64 {
    let scaled = k as i128 * 1_000_000_000 * i128::from(den);
    ((scaled + i128::from(num) / 2) / i128::from(num)) as i64
}

/// Writes the full layout: 60 frames (keys at 0 and 30) first, then 100
/// audio packets, the last with a 5 ms DiscardPadding; ends both, finishes.
fn write_full(path: &Path) {
    let w = Webm::open(path, &full_layout()).expect("open");
    for k in 0..60 {
        w.add(V, frame_ns(k, 30, 1), k % 30 == 0, 0, &frame(k)).expect("video");
    }
    for k in 0..100 {
        let discard = if k == 99 { 5_000_000 } else { 0 };
        w.add(A, k as i64 * 20_000_000, true, discard, &opus(k)).expect("audio");
    }
    w.end(V).expect("end video");
    w.end(A).expect("end audio");
    w.finish().expect("finish");
}

fn opus_head() -> Vec<u8> {
    let mut out = b"OpusHead".to_vec();
    out.extend([1, 2]);
    out.extend(PRE_SKIP.to_le_bytes());
    out.extend(48_000u32.to_le_bytes());
    out.extend([0, 0, 0]);
    out
}

#[test]
fn a_file_reads_back_through_the_216r_reader() {
    let path = temp_path("full");
    write_full(&path);
    let c = Container::open(&path).expect("the reader opens it");
    let d = c.describe();
    assert_eq!(d["doc_type"], json!("webm"));
    let v = &d["video"];
    assert_eq!(v["codec_id"], json!("V_AV1"));
    assert_eq!(v["fourcc"], json!("av01"));
    assert_eq!(v["atom"], json!("av1C"));
    assert_eq!(v["atom_hex"], json!(hex(&AV1C)));
    assert_eq!((v["width"].clone(), v["height"].clone()), (json!(640), json!(360)));
    assert_eq!((v["transfer"].clone(), v["primaries"].clone()), (json!(16), json!(9)));
    assert_eq!(v["matrix"], json!(9));
    assert_eq!(v["mdcv_hex"], json!(mdcv()));
    assert_eq!(v["clli_hex"], json!(CLLI));
    assert_eq!(v["samples"], json!(60));
    let a = &d["audio"];
    assert_eq!(a["codec_id"], json!("A_OPUS"));
    assert_eq!(a["fourcc"], json!("opus"));
    assert_eq!(a["cookie_hex"], json!(hex(&opus_head())));
    assert_eq!((a["sample_rate"].clone(), a["channels"].clone()), (json!(48000), json!(2)));
    assert_eq!(a["samples"], json!(100));
}

#[test]
fn audio_is_timed_from_the_codec_delay() {
    let path = temp_path("delay");
    write_full(&path);
    let c = Container::open(&path).expect("open");
    let n = c.sample_count(AUDIO);
    assert_eq!(n, 100);
    for k in 0..n {
        let s = c.sample(AUDIO, k).expect("a sample");
        assert_eq!(s.pts, k as i64 * 960 - i64::from(PRE_SKIP), "packet {k}");
        assert_eq!(s.frames, 960, "packet {k}");
        assert!(s.sync, "packet {k}");
    }
}

#[test]
fn video_retimes_onto_the_grid_at_every_rate() {
    for (num, den) in [(24_000, 1001), (25, 1), (30, 1), (30_000, 1001), (60, 1)] {
        let path = temp_path("grid");
        let layout = json!({"duration_ns": 3 * SECOND, "video": video_layout([num, den], false)});
        let w = Webm::open(&path, &layout).expect("open");
        let count = (3 * num / den) as usize;
        let mut times = Vec::new();
        for k in 0..count {
            let ns = frame_ns(k, num, den);
            times.push(ns);
            w.add(V, ns, k % 48 == 0, 0, &frame(k)).expect("add");
        }
        w.finish().expect("finish");
        let mut c = Container::open(&path).expect("open");
        assert!(c.retime(Fps { num, den }), "{num}/{den} is off the grid");
        assert_eq!(c.describe()["video"]["timescale"], json!(num));
        for k in 0..count {
            let s = c.sample(VIDEO, k as u64).expect("a sample");
            assert_eq!(s.pts, k as i64 * i64::from(den), "{num}/{den} frame {k}");
        }
        // Each block's time is the pts rounded half up to a millisecond.
        let bytes = std::fs::read(&path).expect("read");
        let (_, seg) = segment(&bytes);
        let read: Vec<i64> = blocks(&bytes, &seg).iter().map(|b| b.ms).collect();
        let want: Vec<i64> = times.iter().map(|ns| (ns + 500_000) / 1_000_000).collect();
        assert_eq!(read, want, "{num}/{den}");
    }
}

#[test]
fn payloads_and_sync_flags_are_the_packets() {
    let path = temp_path("payload");
    write_full(&path);
    let bytes = std::fs::read(&path).expect("read");
    let c = Container::open(&path).expect("open");
    for k in 0..60usize {
        let s = c.sample(VIDEO, k as u64).expect("video");
        let at = s.offset as usize;
        assert_eq!(&bytes[at..at + s.size as usize], frame(k).as_slice(), "frame {k}");
        assert_eq!(s.sync, k % 30 == 0, "frame {k}");
    }
    for k in 0..100usize {
        let s = c.sample(AUDIO, k as u64).expect("audio");
        let at = s.offset as usize;
        assert_eq!(&bytes[at..at + s.size as usize], opus(k).as_slice(), "packet {k}");
    }
}

fn find<'a>(e: &'a Element, id: u32) -> &'a Element {
    e.child(id).unwrap_or_else(|| panic!("no {id:#x} under {:#x}", e.id))
}

#[test]
fn the_walk_finds_the_header_info_and_track_timing() {
    let path = temp_path("walk-head");
    write_full(&path);
    let b = std::fs::read(&path).expect("read");
    let (top, seg) = segment(&b);
    let ebml = &top[0];
    assert_eq!(find(ebml, 0x4282).string(&b), "webm");
    assert_eq!(find(ebml, 0x4287).uint(&b), 4);
    assert_eq!(find(ebml, 0x4285).uint(&b), 2);
    assert_eq!(seg.data + seg.size, b.len(), "the Segment's size is the rest of the file");
    let info = find(&seg, 0x1549_A966);
    assert_eq!(find(info, 0x2A_D7B1).uint(&b), 1_000_000);
    assert_eq!(find(info, 0x4489).float(&b), 2000.0);
    assert_eq!(find(info, 0x4D80).string(&b), "Frame Job");
    assert_eq!(find(info, 0x5741).string(&b), "Frame Job");
    let entries = find(&seg, 0x1654_AE6B).all(0xAE);
    assert_eq!(entries.len(), 2);
    let (v, a) = (entries[0], entries[1]);
    assert_eq!(find(v, 0x23_E383).uint(&b), 33_333_333);
    let colour = find(find(v, 0xE0), 0x55B0);
    assert_eq!(find(colour, 0x55B9).uint(&b), 1);
    assert_eq!(find(colour, 0x55B2).uint(&b), 10);
    assert_eq!(find(colour, 0x55BC).uint(&b), 1000);
    assert_eq!(find(colour, 0x55BD).uint(&b), 0);
    assert_eq!(find(find(colour, 0x55D0), 0x55D9).float(&b), 1000.0);
    assert_eq!(find(a, 0x56AA).uint(&b), 6_500_000);
    assert_eq!(find(a, 0x56BB).uint(&b), 80_000_000);
    assert_eq!(find(find(a, 0xE1), 0xB5).float(&b), 48_000.0);
}

#[test]
fn the_walk_finds_chapters_cues_and_the_seek_head() {
    let path = temp_path("walk");
    write_full(&path);
    let b = std::fs::read(&path).expect("read");
    let (_, seg) = segment(&b);
    // Chapters: one edition, an atom per chapter.
    let edition = find(find(&seg, 0x1043_A770), 0x45B9);
    assert_eq!(find(edition, 0x45BC).uint(&b), 1);
    let atoms = edition.all(0xB6);
    let want = [(0, SECOND, "Intro"), (SECOND, 2 * SECOND, "Body")];
    assert_eq!(atoms.len(), 2);
    for (i, (atom, (start, end, name))) in atoms.iter().zip(want).enumerate() {
        assert_eq!(find(atom, 0x73C4).uint(&b), i as u64 + 1);
        assert_eq!(find(atom, 0x91).uint(&b), start as u64);
        assert_eq!(find(atom, 0x92).uint(&b), end as u64);
        let display = find(atom, 0x80);
        assert_eq!(find(display, 0x85).string(&b), name);
        assert_eq!(find(display, 0x437C).string(&b), "und");
    }
    // Cues: one per key-started Cluster, at its time and position.
    let read = blocks(&b, &seg);
    let mut key_clusters = Vec::new();
    for cluster in seg.all(0x1F43_B675) {
        let first = read.iter().find(|r| r.cluster_start == cluster.start).expect("a block");
        if first.track == 1 && first.flags & 0x80 != 0 {
            key_clusters.push((first.ms as u64, (cluster.start - seg.data) as u64));
        }
    }
    let cues: Vec<(u64, u64)> = find(&seg, 0x1C53_BB6B)
        .all(0xBB)
        .iter()
        .map(|p| {
            let pos = find(p, 0xB7);
            assert_eq!(find(pos, 0xF7).uint(&b), 1);
            (find(p, 0xB3).uint(&b), find(pos, 0xF1).uint(&b))
        })
        .collect();
    assert_eq!(cues, vec![(0, key_clusters[0].1), (1000, key_clusters[1].1)]);
    assert_eq!(cues, key_clusters);
    // Every video key starts its Cluster.
    for r in read.iter().filter(|r| r.track == 1 && r.flags & 0x80 != 0) {
        let first = read.iter().find(|x| x.cluster_start == r.cluster_start).expect("first");
        assert!(std::ptr::eq(first, r), "the key at {} ms does not start its Cluster", r.ms);
    }
    // The SeekHead is the Segment's first child, and each entry resolves.
    let head = &seg.children[0];
    assert_eq!(head.id, 0x114D_9B74);
    let mut ids = Vec::new();
    for seek in head.all(0x4DBB) {
        let id = find(seek, 0x53AB).uint(&b) as u32;
        let at = seg.data + find(seek, 0x53AC).uint(&b) as usize;
        let target = seg.children.iter().find(|e| e.start == at).expect("an element there");
        assert_eq!(target.id, id, "the seek to {id:#x}");
        ids.push(id);
    }
    assert_eq!(ids, [0x1549_A966, 0x1654_AE6B, 0x1043_A770, 0x1C53_BB6B]);
}

#[test]
fn blocks_interleave_in_time_and_the_tail_carries_its_discard_padding() {
    let path = temp_path("order");
    write_full(&path);
    let b = std::fs::read(&path).expect("read");
    let (_, seg) = segment(&b);
    let read = blocks(&b, &seg);
    assert_eq!(read.len(), 160);
    for pair in read.windows(2) {
        let (x, y) = (&pair[0], &pair[1]);
        assert!(x.ms <= y.ms, "{} ms before {} ms", x.ms, y.ms);
        if x.ms == y.ms {
            assert!(x.track <= y.track, "audio before video at {} ms", x.ms);
        }
    }
    let audio: Vec<&ebml_read::BlockRead> = read.iter().filter(|r| r.track == 2).collect();
    for (k, r) in audio.iter().enumerate() {
        if k == 99 {
            assert_eq!(r.discard, Some(5_000_000));
        } else {
            assert_eq!((r.discard, r.flags), (None, 0x80), "packet {k}");
        }
    }
}

#[test]
fn a_cluster_starts_before_its_relative_time_passes_32767_ms() {
    let path = temp_path("long");
    let layout = json!({"duration_ns": 40 * SECOND, "video": video_layout([1, 1], false)});
    let w = Webm::open(&path, &layout).expect("open");
    for k in 0..40usize {
        w.add(V, k as i64 * SECOND, k == 0, 0, &frame(k)).expect("add");
    }
    w.finish().expect("finish");
    let b = std::fs::read(&path).expect("read");
    let (_, seg) = segment(&b);
    let clusters = seg.all(0x1F43_B675);
    let times: Vec<u64> = clusters.iter().map(|c| find(c, 0xE7).uint(&b)).collect();
    assert_eq!(times, vec![0, 33_000]);
    assert_eq!(find(&seg, 0x1C53_BB6B).all(0xBB).len(), 1, "only the key-started one");
}

#[test]
fn a_video_only_layout_writes_each_packet_as_it_arrives() {
    let path = temp_path("video-only");
    let layout = json!({"duration_ns": SECOND, "video": video_layout([30, 1], false)});
    let w = Webm::open(&path, &layout).expect("open");
    for k in 0..30usize {
        w.add(V, frame_ns(k, 30, 1), k == 0, 0, &frame(k)).expect("add");
        let on_disk = std::fs::read(&path).expect("read");
        let packet = frame(k);
        assert!(
            on_disk.windows(packet.len()).any(|w| w == packet.as_slice()),
            "frame {k} is not on disk before the next add"
        );
    }
    assert_eq!(w.add(A, 0, true, 0, &opus(0)), Err("track 2 is not in the layout".into()));
    w.finish().expect("finish");
    let b = std::fs::read(&path).expect("read");
    let (_, seg) = segment(&b);
    assert_eq!(find(&seg, 0x1654_AE6B).all(0xAE).len(), 1);
    let c = Container::open(&path).expect("open");
    assert!(c.describe()["audio"].is_null());
    assert_eq!(c.sample_count(VIDEO), 30);
}

#[test]
fn every_layout_refusal_is_its_sentence() {
    let video = video_layout([30, 1], false);
    let mut cases: Vec<(Value, String)> = Vec::new();
    let with = |key: &str, value: Value| {
        let mut l = full_layout();
        l["video"][key] = value;
        l
    };
    cases.push((json!({"duration_ns": SECOND}), "the layout has no video and no audio track".into()));
    cases.push((with("codec_id", json!("V_VP9")), "video codec_id \"V_VP9\" is not V_AV1".into()));
    cases.push((with("codec_private_hex", json!("")), "the V_AV1 codec_private_hex is empty".into()));
    cases.push((with("codec_private_hex", json!("8z")), "codec_private_hex \"8z\" is not hex".into()));
    cases.push((with("width", json!(0)), "the video size 0 × 360 has a side of 0".into()));
    cases.push((with("fps", json!([30, 0])), "the video fps [30, 0] is not a rate".into()));
    let mut l = full_layout();
    l["video"]["colour"]["mdcv_hex"] = json!("0011");
    cases.push((l, "mdcv_hex is 2 bytes, not 24".into()));
    let mut l = full_layout();
    l["video"]["colour"]["clli_hex"] = json!("03e8");
    cases.push((l, "clli_hex is 2 bytes, not 4".into()));
    let mut l = full_layout();
    l["video"]["colour"]["clli_hex"] = json!("03e800");
    cases.push((l, "clli_hex \"03e800\" is not hex".into()));
    let mut l = full_layout();
    l["audio"]["codec_id"] = json!("A_VORBIS");
    cases.push((l, "audio codec_id \"A_VORBIS\" is not A_OPUS".into()));
    let mut l = full_layout();
    l["audio"]["sample_rate"] = json!(44100);
    cases.push((l, "audio sample_rate 44100 is not 48000".into()));
    let mut l = full_layout();
    l["audio"]["channels"] = json!(3);
    cases.push((l, "audio channels 3 is not 1 or 2".into()));
    let mut l = json!({"duration_ns": SECOND, "video": video.clone()});
    l["chapters"] = json!([{"start_ns": 5, "end_ns": 5, "name": "A"}]);
    cases.push((l, "chapter 1 \"A\" ends at 5 ns, not after its start at 5 ns".into()));
    let mut l = json!({"duration_ns": SECOND, "video": video});
    l["chapters"] = json!([{"start_ns": 0, "end_ns": 9, "name": "A"},
                           {"start_ns": SECOND, "end_ns": 2 * SECOND, "name": "B"}]);
    cases.push((l, format!("chapter 2 \"B\" starts at {SECOND} ns, not before the duration {SECOND} ns")));
    for (layout, sentence) in cases {
        let path = temp_path("refused");
        assert_eq!(Webm::open(&path, &layout).err(), Some(sentence.clone()), "{layout}");
        assert!(!path.exists(), "a refused layout made a file: {sentence}");
    }
    let mut l = full_layout();
    l["extra"] = json!(1);
    let read = Webm::open(&temp_path("unknown"), &l).err().expect("refused");
    assert!(read.starts_with("the layout could not be read: unknown field `extra`"), "{read}");
    let path = Path::new("/nonexistent-framejob-folder/x.webm");
    let made = Webm::open(path, &full_layout()).err().expect("refused");
    assert!(made.starts_with("the file could not be created ("), "{made}");
}

#[test]
fn every_packet_refusal_is_its_sentence() {
    let w = Webm::open(&temp_path("packets"), &full_layout()).expect("open");
    assert_eq!(w.add(3, 0, true, 0, &[1]), Err("track 3 is not in the layout".into()));
    assert_eq!(w.add(V, -1, true, 0, &[1]), Err("pts -1 ns on track 1 is negative".into()));
    w.add(V, 100, true, 0, &[1]).expect("first");
    assert_eq!(
        w.add(V, 100, false, 0, &[2]),
        Err("pts 100 ns on track 1 is not after its last, 100 ns".into())
    );
    w.end(A).expect("end audio");
    assert_eq!(w.add(A, 0, true, 0, &[1]), Err("track 2 has ended".into()));
    assert_eq!(w.end(A), Err("track 2 has ended".into()));
    w.finish().expect("finish");
    assert_eq!(w.add(V, 200, false, 0, &[3]), Err("the file is finished".into()));
    assert_eq!(w.end(V), Err("the file is finished".into()));
    assert_eq!(w.finish(), Err("the file is finished".into()));
}

#[test]
fn two_threads_add_at_once() {
    let path = temp_path("threads");
    let w = Webm::open(&path, &full_layout()).expect("open");
    std::thread::scope(|scope| {
        scope.spawn(|| {
            for k in 0..60 {
                w.add(V, frame_ns(k, 30, 1), k % 30 == 0, 0, &frame(k)).expect("video");
            }
            w.end(V).expect("end video");
        });
        scope.spawn(|| {
            for k in 0..100 {
                w.add(A, k as i64 * 20_000_000, true, 0, &opus(k)).expect("audio");
            }
            w.end(A).expect("end audio");
        });
    });
    w.finish().expect("finish");
    let b = std::fs::read(&path).expect("read");
    let (_, seg) = segment(&b);
    let read = blocks(&b, &seg);
    assert_eq!(read.len(), 160);
    assert!(read.windows(2).all(|p| p[0].ms <= p[1].ms), "the blocks are out of order");
    let c = Container::open(&path).expect("open");
    assert_eq!((c.sample_count(VIDEO), c.sample_count(AUDIO)), (60, 100));
}

