            mBytesPerPacket: 0, mFramesPerPacket: UInt32(Self.framesPerPacket),
            mBytesPerFrame: 0, mChannelsPerFrame: UInt32(Self.channels), mBitsPerChannel: 0,
            mReserved: 0)
