    /// Reads the mix to its end, encodes it and adds each packet at k × 20 ms, holding the
    /// newest back so the last one can carry the tail's DiscardPadding (CX-15 (5)).
    private func pumpAudio(
        _ output: AVAssetReaderOutput, into webm: ReelWebM, through opus: ExportOpusEncoder
    ) {
        let gain = audioGain
        var held: Data?
        var added: Int64 = 0
        let add = { (packet: Data, padding: Int64) throws in
            try webm.add(
                track: ReelWebM.audio, ptsNs: added * 20_000_000, key: true,
                discardPaddingNs: padding, data: packet)
