 * clli and mdcv through meta's pitm and iprp; the same JSON; NULL or 0 length reads {}. */
char *rc_hdr10_still_peak(const uint8_t *file, size_t file_len);

/* av1 — §11 CX-12 (4): AV1 in MP4's container bytes, decided by the core
 * (core/src/av1_mp4.rs, ffi_av1.rs); the encoder is the app's (CX-4). The av1C
 * record from the first sequence header OBU in `obus`, parsed per AV1 §5.5 through
 * color_config: JSON {"av1c_hex","seq_profile","seq_level_idx","seq_tier",
 * "bit_depth","monochrome","color":{"primaries","transfer","matrix","full_range"}},
